func labController(t *testing.T, instance, dir string) Config {
	t.Helper()
	cfg := productionTestConfig(t, "gru", instance)
	cfg.Embedded.StoreDir = dir
	return cfg
}

func pinNodeIdentity(dir, cell, instance, nodeID string) error {
	return pinNodeIdentityWithSync(dir, cell, instance, nodeID, syncIdentityDirectory)
}

func pinNodeIdentityWithSync(dir, cell, instance, nodeID string, syncDirectory func(string) error) error {
	if cell == "" || instance == "" || !validNodeID(nodeID) {
		return fmt.Errorf("%w: invalid Raft store identity", ErrStoreIdentity)
	}
	want := nodeIdentity{Version: 1, Cell: cell, Instance: instance, NodeID: nodeID}
	path := filepath.Join(dir, nodeIdentityFile)
	check := func() error {
		info, err := os.Lstat(path)
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() > 1024 {
			return fmt.Errorf("%w: invalid node identity file", ErrStoreIdentity)
		}
		wire, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var recorded nodeIdentity
		if err := protocol.DecodeStrict(wire, &recorded, 1024); err != nil || recorded != want {
			return fmt.Errorf("%w: node identity differs from this cell/controller and Raft ID", ErrStoreIdentity)
		}
		return nil
	}
	if err := check(); !errors.Is(err, fs.ErrNotExist) {
		if err != nil {
			return err
		}
		return syncDirectory(dir)
	}
	wire, err := json.Marshal(want)
	if err != nil {
		return err
	}
	temp, err := os.CreateTemp(dir, "node-identity.*")
	if err != nil {
		return err
	}
	defer os.Remove(temp.Name())
	defer temp.Close()
	if _, err := temp.Write(wire); err != nil {
		return err
	}
	if err := temp.Sync(); err != nil {
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	// Link publishes a complete record without replacing another starter's pin.
	if err := os.Link(temp.Name(), path); err != nil && !errors.Is(err, fs.ErrExist) {
		return err
	}
	if err := syncDirectory(dir); err != nil {
		return err
	}
	return check()
}

func syncIdentityDirectory(dir string) error {
	directory, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func validNodeID(id string) bool {
	if len(id) != 8 {
		return false
	}
	for _, ch := range id {
		if !(ch >= '0' && ch <= '9' || ch >= 'A' && ch <= 'Z' || ch >= 'a' && ch <= 'z') {
			return false
		}
	}
	return true
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func serverOptions(cfg Config) (*server.Options, error) {
	return serverOptionsForStart(cfg, false)
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func pinStoreIdentity(dir, name, legacy string) error {
	path := filepath.Join(dir, storeIdentityFile)
	recorded, err := os.ReadFile(path)
	if err == nil {
		if owner := strings.TrimSuffix(string(recorded), "\n"); owner != name {
			return fmt.Errorf("%w: store %s belongs to %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, owner, name)
		}
		return nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("read NATS store identity: %w", err)
	}
	if name != legacy {
		entries, err := os.ReadDir(filepath.Join(dir, "jetstream"))
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read NATS store: %w", err)
		}
		if len(entries) > 0 {
			return fmt.Errorf("%w: store %s holds JetStream state of %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, legacy, name)
		}
	}
	temp, err := os.CreateTemp(dir, storeIdentityFile+".*")
	if err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	defer os.Remove(temp.Name())
	if _, err := temp.WriteString(name + "\n"); err != nil {
		temp.Close()
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	return os.Rename(temp.Name(), path)
}

contract.text:
func sameFlow(kind jwt.ExportType, subject string) contractFlow {
	return contractFlow{kind: kind, cellSubject: subject, linkSubject: subject}
}

// globalMirrorFlows are the home-side subjects of peer's global mirror.
func globalMirrorFlows(home, peer string) []contractFlow {
	consumer := protocol.GlobalMirrorConsumer(peer)
	return []contractFlow{
		sameFlow(jwt.Stream, protocol.InterRegionGlobalDeliverSubject(peer)),
		{
			kind:        jwt.Service,
			cellSubject: protocol.JSConsumerResetSubject(protocol.JSLocalAPIPrefix, protocol.GlobalControlStream, consumer),
			linkSubject: protocol.JSConsumerResetSubject(protocol.JSDomainAPIPrefix(home), protocol.GlobalControlStream, consumer),
		},
		sameFlow(jwt.Service, protocol.JSFlowControlSubject(protocol.GlobalControlStream, consumer)),
	}
}

// observabilityFlows are cell's read-only telemetry services: exact
// request/reply subjects (region summary, decision query), never a wildcard
// over the observability leaves, so member snapshots and the raw journal
// stream stay regional. Their responders validate every request strictly.
func observabilityFlows(cell string) []contractFlow {
	var flows []contractFlow
	for _, leaf := range protocol.InterRegionObservabilityLeaves() {
		flows = append(flows, sameFlow(jwt.Service, protocol.InterRegionObservabilitySubject(cell, leaf)))
	}
	return flows
}

// outbound flows are exported by the cell account and imported by the
// interregion account: what this region offers to its peers.
func (c InterRegionContract) outbound() []contractFlow {
	flows := []contractFlow{
		sameFlow(jwt.Stream, protocol.RegionHealthSubject(c.Cell)),
		sameFlow(jwt.Service, protocol.Regional(c.Cell, "query", ">")),
	}
	flows = append(flows, observabilityFlows(c.Cell)...)
	if c.GlobalHome == c.Cell {
		for _, peer := range c.Peers {
			flows = append(flows, globalMirrorFlows(c.Cell, peer)...)
		}
	}
	return flows
}

// inbound flows are exported by the interregion account and imported by the
// cell account: what this region takes from its peers.
func (c InterRegionContract) inbound() []contractFlow {
	var flows []contractFlow
	for _, peer := range c.Peers {
		flows = append(flows,
			sameFlow(jwt.Stream, protocol.RegionHealthSubject(peer)),
			sameFlow(jwt.Service, protocol.Regional(peer, "query", ">")))
		flows = append(flows, observabilityFlows(peer)...)
	}
	if c.GlobalHome != "" && c.GlobalHome != c.Cell {
		// A mirror addresses the home region only by the link subjects.
		for _, flow := range globalMirrorFlows(c.GlobalHome, c.Cell) {
			flows = append(flows, sameFlow(flow.kind, flow.linkSubject))
		}
	}
	return flows
}

func (c InterRegionContract) ChildLeafPermissions(child string) jwt.Permissions {
	subtree, ok := c.Subtrees[child]
	if !ok {
		return denyAllPermissions()
	}
	return c.leafPermissionsFor(func(region string) bool { return slices.Contains(subtree, region) })
}

// LeafPermissions is the union of every possible child's permissions: the
// most any leaf of this region could be granted. It is a review aid; leaf
// users get ChildLeafPermissions through their child's scoped signing key.
func (c InterRegionContract) LeafPermissions() jwt.Permissions {
	return c.leafPermissionsFor(func(string) bool { return true })
}

// denyAllPermissions are the interregion account's default permissions: a
// leaf user not issued by a child's scoped signing key may do nothing.
func denyAllPermissions() jwt.Permissions {
	var permissions jwt.Permissions
	permissions.Pub.Deny.Add(">")
	permissions.Sub.Deny.Add(">")
	return permissions
}

func (c InterRegionContract) leafPermissionsFor(inSubtree func(string) bool) jwt.Permissions {
	var permissions jwt.Permissions
	for _, region := range append([]string{c.Cell}, c.Peers...) {
		permissions.Sub.Allow.Add(protocol.RegionHealthSubject(region))
		permissions.Pub.Allow.Add(protocol.Regional(region, "query", ">"))
		for _, flow := range observabilityFlows(region) {
			permissions.Pub.Allow.Add(flow.linkSubject)
		}
		if region == c.Cell || region == c.GlobalHome || !inSubtree(region) {
			continue
		}
		permissions.Pub.Allow.Add(protocol.RegionHealthSubject(region))
		permissions.Sub.Allow.Add(protocol.Regional(region, "query", ">"))
		for _, flow := range observabilityFlows(region) {
			permissions.Sub.Allow.Add(flow.linkSubject)
		}
		if c.GlobalHome == "" {
			continue
		}
		for _, flow := range globalMirrorFlows(c.GlobalHome, region) {
			if flow.kind == jwt.Stream {
				permissions.Sub.Allow.Add(flow.linkSubject)
			} else {
				permissions.Pub.Allow.Add(flow.linkSubject)
			}
		}
	}
	permissions.Pub.Allow.Add(leafReplyGrant)
	permissions.Sub.Allow.Add(leafReplyGrant)
	return permissions
}

// CellExports is what the cell account offers to its interregion account.
func (c InterRegionContract) CellExports() jwt.Exports {
	var exports jwt.Exports
	for _, flow := range c.outbound() {
		exports.Add(&jwt.Export{Name: "interregion", Subject: jwt.Subject(flow.cellSubject), Type: flow.kind})
	}
	return exports
}

const (
	ObservabilityRegionLeaf    = "region"
	ObservabilityDecisionsLeaf = "decisions"
)

// InterRegionObservabilityLeaves lists the observability leaves exported to
// peer regions, in contract order.
func InterRegionObservabilityLeaves() []string {
	return []string{ObservabilityRegionLeaf, ObservabilityDecisionsLeaf}
}

// InterRegionObservabilitySubject is the exact subject of one exported
// observability leaf of cell, for example ts.orch.v1.gru.obs.region.
func InterRegionObservabilitySubject(cell, leaf string) string { return Regional(cell, "obs", leaf) }

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

func QuerySubject(region, query string) (string, error) {
	return regionalSubject(region, "query", query)
}

func CommandSubject(region, command string) (string, error) {
	return regionalSubject(region, "command", command)
}

// ObservabilitySubject is a read-only member telemetry route inside one
// regional cell, for example ts.orch.v1.gru.obs.snapshot. Every controller
// answers it; it carries no signed state and never drives a mutation.
// ObservabilityGrant (families.go) is the subscribe grant covering every leaf.
func ObservabilitySubject(region, leaf string) (string, error) {
	return regionalSubject(region, "obs", leaf)
}

