func productionPreflightFixture(t *testing.T) (Config, nkeys.KeyPair, nkeys.KeyPair, *jwt.UserClaims) {
	t.Helper()
	root := t.TempDir()
	operatorKey, _ := nkeys.CreateOperator()
	systemKey, _ := nkeys.CreateAccount()
	cellKey, _ := nkeys.CreateAccount()
	operatorID, _ := operatorKey.PublicKey()
	systemID, _ := systemKey.PublicKey()
	cellID, _ := cellKey.PublicKey()
	operator := jwt.NewOperatorClaims(operatorID)
	operator.SystemAccount = systemID
	operatorRaw, err := operator.Encode(operatorKey)
	if err != nil {
		t.Fatal(err)
	}
	systemRaw, err := jwt.NewAccountClaims(systemID).Encode(operatorKey)
	if err != nil {
		t.Fatal(err)
	}
	cellRaw, err := jwt.NewAccountClaims(cellID).Encode(operatorKey)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, content string) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	systemUser, _ := nkeys.CreateUser()
	systemUserID, _ := systemUser.PublicKey()
	systemCreds := testJWTUserCredentialsWithKey(t, root, "system.creds", systemKey, systemID, systemUser,
		[]string{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"},
		[]string{inboxPrefix("gru", systemUserID) + ".>"})
	controllerUser, _ := nkeys.CreateUser()
	controllerID, _ := controllerUser.PublicKey()
	controller := jwt.NewUserClaims(controllerID)
	controller.IssuerAccount = cellID
	controller.Pub.Allow = jwt.StringList{"ts.broker.gru.ticket.>", "ts.broker.gru.fence.>"}
	controller.Sub.Allow = jwt.StringList{
		inboxPrefix("gru", controllerID) + ".>", "ts.broker.gru.ticket.>",
		"ts.broker.gru.fence.broker-a", "ts.orch.v1.gru.broker.claim.apply",
		"ts.orch.v1.gru.managed-update.prepare",
		"ts.orch.v1.gru.backup.operation",
		"ts.orch.v1.gru.terminal.>",
	}
	controller.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	controllerCreds := writeControllerPreflightCredentials(t, root, controller, cellKey, controllerUser)
	tlsFiles := testBridgeTLS(t, filepath.Join(root, "tls"))
	ticketPublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	cfg := Config{Cell: "gru", Instance: "broker-a", Replicas: 1, CredentialsFile: controllerCreds,
		TLS: tlsFiles, Embedded: &Embedded{
			Host: "127.0.0.1", Port: 4222, StoreDir: filepath.Join(root, "store"),
			TLS: tlsFiles, RouteTLS: tlsFiles, OperatorJWTFile: write("operator.jwt", operatorRaw),
			SystemJWTFile: write("system.jwt", systemRaw), CellJWTFile: write("cell.jwt", cellRaw),
			SystemCredentialsFile: systemCreds, TicketPublicKeyFile: write("ticket.pub", base64.StdEncoding.EncodeToString(ticketPublic)),
			BrokerIDs: []string{"broker-a"},
		}}
	return cfg, cellKey, controllerUser, controller
}

func writeControllerPreflightCredentials(t *testing.T, root string, claim *jwt.UserClaims, account, user nkeys.KeyPair) string {
	t.Helper()
	raw, err := claim.Encode(account)
	if err != nil {
		t.Fatal(err)
	}
	seed, err := user.Seed()
	if err != nil {
		t.Fatal(err)
	}
	content, err := jwt.FormatUserConfig(raw, seed)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(root, "controller.creds")
	if err := os.WriteFile(path, content, 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func validateCurrentTLSFiles(files TLSFiles, role string) error {
	config, err := loadTLS(files, false)
	if err != nil {
		return err
	}
	if len(config.Certificates) != 1 || len(config.Certificates[0].Certificate) == 0 {
		return errors.New("TLS certificate chain is missing")
	}
	leaf, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
	if err != nil {
		return fmt.Errorf("parse TLS leaf certificate: %w", err)
	}
	return verifyTLSLeaf(leaf, config.Certificates[0].Certificate[1:], config.RootCAs, role)
}

// verifyTLSLeaf checks that a leaf is current and chains to roots for each
// usage its role needs: client, listener or route (both ends).
func verifyTLSLeaf(leaf *x509.Certificate, chain [][]byte, roots *x509.CertPool, role string) error {
	intermediates := x509.NewCertPool()
	for _, der := range chain {
		certificate, err := x509.ParseCertificate(der)
		if err != nil {
			return fmt.Errorf("parse TLS intermediate certificate: %w", err)
		}
		intermediates.AddCert(certificate)
	}
	var usages []x509.ExtKeyUsage
	switch role {
	case "client":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
	case "listener":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}
	case "route":
		usages = []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}
	default:
		return fmt.Errorf("unsupported TLS certificate role %q", role)
	}
	for _, usage := range usages {
		if _, err := leaf.Verify(x509.VerifyOptions{
			Roots: roots, Intermediates: intermediates, CurrentTime: time.Now(),
			KeyUsages: []x509.ExtKeyUsage{usage},
		}); err != nil {
			return fmt.Errorf("verify current TLS certificate chain: %w", err)
		}
	}
	return nil
}

func loadOperatorAccounts(e *Embedded) (*jwt.OperatorClaims, string, string, string, string, error) {
	operatorRaw, err := readSignedJWT(e.OperatorJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional operator JWT: %w", err)
	}
	operator, err := jwt.DecodeOperatorClaims(operatorRaw)
	if err != nil || !nkeys.IsValidPublicOperatorKey(operator.Subject) ||
		!nkeys.IsValidPublicAccountKey(operator.SystemAccount) {
		return nil, "", "", "", "", errors.New("regional operator JWT is invalid")
	}
	systemRaw, err := readSignedJWT(e.SystemJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional system JWT: %w", err)
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil || system.Subject != operator.SystemAccount || !operator.DidSign(system) {
		return nil, "", "", "", "", errors.New("regional system account JWT is invalid")
	}
	cellRaw, err := readSignedJWT(e.CellJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional cell JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil || !nkeys.IsValidPublicAccountKey(cell.Subject) ||
		cell.Subject == system.Subject || !operator.DidSign(cell) {
		return nil, "", "", "", "", errors.New("regional cell account JWT is invalid")
	}
	return operator, systemRaw, cellRaw, system.Subject, cell.Subject, nil
}

func credentialUser(path string) (*jwt.UserClaims, string, error) {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return nil, "", err
	}
	defer clear(data)
	return credentialUserBytes(data)
}

func credentialUserBytes(data []byte) (*jwt.UserClaims, string, error) {
	raw, err := nkeys.ParseDecoratedJWT(data)
	if err != nil {
		return nil, "", err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, "", err
	}
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, "", err
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil || public != claim.Subject {
		return nil, "", errors.New("regional credential seed and user JWT differ")
	}
	if claim.BearerToken || claim.ProxyRequired || len(claim.Src) != 0 ||
		len(claim.AllowedConnectionTypes) != 0 && !claim.AllowedConnectionTypes.Contains(jwt.ConnectionTypeInProcess) {
		return nil, "", errors.New("regional JWT depends on client metadata unavailable through the bridge")
	}
	return claim, public, nil
}

func credentialAccount(claim *jwt.UserClaims) string {
	if claim.IssuerAccount != "" {
		return claim.IssuerAccount
	}
	return claim.Issuer
}

func ValidateBrokerControllerCredentials(path, cell, broker string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	defer clear(data)
	return ValidateBrokerControllerCredentialBytes(data, cell, broker)
}

// ValidateBrokerControllerCredentialBytes checks the same contract before a
// root-signed material generation installs controller credentials.
func ValidateBrokerControllerCredentialBytes(data []byte, cell, broker string) error {
	if !cellName.MatchString(cell) || !cellName.MatchString(broker) {
		return errors.New("broker controller credential cell or instance is invalid")
	}
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	ticket := protocol.Broker(cell, "ticket", ">")
	fencePublish := protocol.Broker(cell, "fence", ">")
	fenceReceive := protocol.Broker(cell, "fence", broker)
	if !slices.Contains(claim.Pub.Allow, ticket) || !slices.Contains(claim.Pub.Allow, fencePublish) ||
		!slices.Contains(claim.Sub.Allow, ticket) || !slices.Contains(claim.Sub.Allow, fenceReceive) {
		return errors.New("broker controller credentials lack ticket or instance-bound fence grants")
	}
	allowedSubscriptions := map[string]bool{
		inboxPrefix(cell, public) + ".>": true,
		ticket:                           true, fenceReceive: true,
	}
	for _, subject := range ControllerSubscriptions(cell) {
		allowedSubscriptions[subject] = true
	}
	for _, subject := range GlobalControllerRequests() {
		allowedSubscriptions[subject] = true
	}
	// Optional read-only member telemetry (observability snapshots). The
	// issuer does not grant it today; it is accepted, not required.
	allowedSubscriptions[protocol.ObservabilityGrant(cell)] = true
	for _, grant := range claim.Sub.Allow {
		if !allowedSubscriptions[grant] {
			return fmt.Errorf("broker controller credentials have unscoped subscription %q", grant)
		}
	}
	if !slices.Contains(claim.Sub.Allow, inboxPrefix(cell, public)+".>") ||
		!slices.Contains(claim.Sub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.ManagedUpdatePrepareSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.TerminalSubject(cell, ">")) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 ||
		claim.Resp == nil || claim.Resp.MaxMsgs != 1 ||
		claim.Resp.Expires <= 0 || claim.Resp.Expires > 5*time.Second {
		return errors.New("broker controller credentials need a private inbox and one bounded response grant")
	}
	return nil
}

// ValidateBrokerOperatorCredentials requires exact publishes for claim apply,
// backup operations and terminal requests, JetStream INFO and control-stream
// INFO/MSG.GET read grants, and the caller's private inbox. These are the
// production issuer grants needed by the CLI's
// readiness and authority observation before publishing its signed request.
func ValidateBrokerOperatorCredentials(path, cell string) error {
	if !cellName.MatchString(cell) {
		return errors.New("broker operator credential cell is invalid")
	}
	claim, public, err := credentialUser(path)
	if err != nil {
		return fmt.Errorf("broker operator credentials: %w", err)
	}
	allowedPublishes := BrokerOperatorPublishPermissions(cell)
	for _, grant := range claim.Pub.Allow {
		if !slices.Contains(allowedPublishes, grant) {
			return fmt.Errorf("broker operator credentials have unscoped publish %q", grant)
		}
	}
	if !slices.Contains(claim.Pub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Pub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "plan")) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "apply")) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "status")) ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.INFO") ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.STREAM.INFO.TS_CONTROL_LOG") ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.STREAM.MSG.GET.TS_CONTROL_LOG") ||
		len(claim.Sub.Allow) != 1 || claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 {
		return errors.New("broker operator credentials need claim-apply publish and private reply grants")
	}
	return nil
}

func validateSystemCredentials(path, cell, cellAccount, systemAccount string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	defer clear(data)
	return ValidateSystemCredentials(data, cell, cellAccount, systemAccount)
}

// ValidateSystemCredentials checks a system account credentials file's bytes:
// a seed that matches its JWT, issued by systemAccount, with only the cell
// claim-update and private reply grants.
func ValidateSystemCredentials(data []byte, cell, cellAccount, systemAccount string) error {
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	if credentialAccount(claim) != systemAccount ||
		len(claim.Pub.Allow) != 1 || claim.Pub.Allow[0] != "$SYS.REQ.ACCOUNT."+cellAccount+".CLAIMS.UPDATE" ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Allow) != 1 ||
		claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" || len(claim.Sub.Deny) != 0 ||
		claim.Resp != nil {
		return errors.New("system account credentials must have only the cell claim-update and private reply grants")
	}
	return nil
}

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil
}

func loadTLS(files TLSFiles, serverSide bool) (*tls.Config, error) {
	key, err := readPrivateFile(files.KeyFile, 64<<10)
	if err != nil {
		return nil, fmt.Errorf("NATS TLS private key: %w", err)
	}
	clear(key)
	certificate, err := tls.LoadX509KeyPair(files.CertFile, files.KeyFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS certificate: %w", err)
	}
	ca, err := os.ReadFile(files.CAFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS CA: %w", err)
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(ca) {
		return nil, errors.New("NATS CA file has no certificates")
	}
	config := &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}, RootCAs: roots}
	if serverSide {
		config.ClientCAs = roots
		config.ClientAuth = tls.RequireAndVerifyClientCert
	}
	return config, nil
}

func readPrivateFile(path string, limit int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("secret must be a regular file readable only by its owner")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("secret must be owned by this process user")
	}
	if info.Size() > limit {
		return nil, errors.New("secret file is too large")
	}
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > limit {
		clear(data)
		return nil, errors.New("secret file is too large")
	}
	return data, nil
}

