func TestReconnectInterRegionRepairsLeavesWithoutRestartingRegionalState(t *testing.T) {
	tier.Integration(t)
	ctx, cancel := context.WithTimeout(t.Context(), 90*time.Second)
	defer cancel()
	root := t.TempDir()
	topology := HubAndSpoke("gru", []string{"sfo"})
	leafTLS := testTLSFor(t, filepath.Join(root, "leaf-tls"))
	gru := newTestRegion(t, filepath.Join(root, "gru"), "gru", topology)
	sfo := newTestRegion(t, filepath.Join(root, "sfo"), "sfo", topology)
	brokers := []string{"broker-a", "broker-b", "broker-c"}
	ports := freeClientPorts(t, 9)
	routes := make([]string, len(brokers))
	for index := range brokers {
		routes[index] = fmt.Sprintf("nats-route://127.0.0.1:%d", ports[3+index])
	}
	routeSecret := filepath.Join(root, "route.secret")
	if err := os.WriteFile(routeSecret, []byte("reconnect-test-route-secret"), 0o600); err != nil {
		t.Fatal(err)
	}
	hub := net.JoinHostPort("127.0.0.1", strconv.Itoa(ports[6]))
	private, fallback := newTCPProxy(t, hub), newTCPProxy(t, hub)
	defer private.Close()
	defer fallback.Close()
	sfo.cfg.Embedded.InterRegion.Remotes = []LeafRemote{{
		Peer: "gru", URLs: []string{"nats-leaf://" + private.Addr(), "nats-leaf://" + fallback.Addr()},
		ServerName: testLeafServerName, TLS: leafTLS, PeerAccount: gru.interregionID,
		CredentialsFile: gru.childLeafCredentials(t, "sfo-leaf.creds", "sfo"),
	}}
	var runtimes []*Runtime
	var configs []Config
	t.Cleanup(func() {
		for _, runtime := range runtimes {
			_ = runtime.Close()
		}
	})
	for index := range brokers {
		cfg := gru.cfg
		embedded, interregion := *cfg.Embedded, *cfg.Embedded.InterRegion
		cfg.Embedded, embedded.InterRegion = &embedded, &interregion
		cfg.Instance, cfg.Replicas = brokers[index], 3
		embedded.Port, embedded.RouteHost, embedded.RoutePort = ports[index], "127.0.0.1", ports[3+index]
		embedded.Routes, embedded.BrokerIDs = PeerRoutes(routes, routes[index]), brokers
		embedded.RouteUser, embedded.RoutePasswordFile = "reconnect-test", routeSecret
		embedded.StoreDir = filepath.Join(root, "gru", brokers[index])
		interregion.Listen = &LeafListen{Host: "0.0.0.0", Port: ports[6+index], TLS: leafTLS}
		runtime, err := Start(ctx, cfg)
		if err != nil {
			t.Fatalf("start gru %s: %v", cfg.Instance, err)
		}
		runtimes, configs = append(runtimes, runtime), append(configs, cfg)
	}
	for _, runtime := range runtimes {
		waitUntil(t, ctx, "regional R3 quorum", func() bool { return runtime.FullClusterReady(3) })
	}
	sfoRuntime, err := Start(ctx, sfo.cfg)
	if err != nil {
		t.Fatalf("start sfo: %v", err)
	}
	runtimes, configs = append(runtimes, sfoRuntime), append(configs, sfo.cfg)
	gruRuntime := runtimes[0]
	subject := protocol.Regional("sfo", "query", "status")
	query, err := sfoRuntime.Conn().Subscribe(subject, func(msg *nats.Msg) { _ = msg.Respond([]byte("sfo-ok")) })
	if err != nil {
		t.Fatal(err)
	}
	defer query.Unsubscribe()
	if err := sfoRuntime.Conn().Flush(); err != nil {
		t.Fatal(err)
	}
	probe := func(ctx context.Context) {
		t.Helper()
		if reply := requestUntil(ctx, t, gruRuntime.Conn(), subject); string(reply.Data) != "sfo-ok" {
			t.Fatalf("authenticated contract reply = %q", reply.Data)
		}
	}
	leaf := func(runtime *Runtime) *server.LeafInfo {
		t.Helper()
		leafz, err := runtime.server.Leafz(&server.LeafzOptions{Account: runtime.resolver.interregion})
		if err != nil || len(leafz.Leafs) != 1 {
			t.Fatalf("interregion leaf = %+v, %v", leafz, err)
		}
		return leafz.Leafs[0]
	}
	waitLeafCount(ctx, t, gruRuntime, 1)
	waitLeafCount(ctx, t, sfoRuntime, 1)
	probe(ctx)

	// These snapshots expose a repair that restarts a broker, route or client,
	// or replaces the persisted regional store instead of reconnecting its leaf.
	type snapshot struct {
		serverID, owner string
		node            nodeIdentity
		routeIDs        []uint64
		reconnects      uint64
	}
	observe := func(index int) snapshot {
		t.Helper()
		runtime := runtimes[index]
		owner, err := os.ReadFile(filepath.Join(configs[index].Embedded.StoreDir, storeIdentityFile))
		if err != nil {
			t.Fatal(err)
		}
		routez, err := runtime.server.Routez(nil)
		if err != nil {
			t.Fatal(err)
		}
		var ids []uint64
		for _, route := range routez.Routes {
			ids = append(ids, route.Rid)
		}
		slices.Sort(ids)
		return snapshot{runtime.server.ID(), string(owner), readNodeIdentity(t, configs[index].Embedded.StoreDir), ids,
			runtime.Conn().Stats().Reconnects}
	}
	before := make([]snapshot, len(runtimes))
	streams := make([]jetstream.Stream, len(runtimes))
	for index, runtime := range runtimes {
		before[index] = observe(index)
		if index < 3 && len(before[index].routeIDs) == 0 {
			t.Fatal("regional route preservation needs live routes")
		}
		name := fmt.Sprintf("RECONNECT_%d", index)
		streams[index], err = runtime.JetStream().CreateStream(ctx, jetstream.StreamConfig{
			Name: name, Subjects: []string{name}, Storage: jetstream.FileStorage, Replicas: configs[index].Replicas,
		})
		if err != nil {
			t.Fatal(err)
		}
		if _, err := runtime.JetStream().Publish(ctx, name, []byte("retained")); err != nil {
			t.Fatal(err)
		}
	}
	assertPreserved := func() {
		t.Helper()
		for index, runtime := range runtimes {
			got, want := observe(index), before[index]
			if !runtime.Ready() || got.serverID != want.serverID || got.owner != want.owner || got.node != want.node ||
				got.reconnects != want.reconnects || !slices.Equal(got.routeIDs, want.routeIDs) {
				t.Fatalf("regional broker %d changed during leaf repair: %+v, want %+v", index, got, want)
			}
			message, err := streams[index].GetMsg(ctx, 1)
			if err != nil || string(message.Data) != "retained" {
				t.Fatalf("regional stored message %d = %+v, %v", index, message, err)
			}
		}
	}

	canceled, stop := context.WithCancel(ctx)
	stop()
	canceledID := leaf(sfoRuntime).ID
	if kicked, err := sfoRuntime.ReconnectInterRegion(canceled); kicked != 0 || !errors.Is(err, context.Canceled) {
		t.Fatalf("canceled reconnect = %d, %v", kicked, err)
	}
	if leaf(sfoRuntime).ID != canceledID {
		t.Fatal("canceled reconnect changed the leaf")
	}
	for _, resolver := range []*accountResolver{nil, {}} {
		unpinned := &Runtime{server: gruRuntime.server, resolver: resolver}
		if kicked, err := unpinned.ReconnectInterRegion(ctx); kicked != 0 || err == nil {
			t.Fatalf("unpinned account reconnect = %d, %v", kicked, err)
		}
	}
	inboundID := leaf(gruRuntime).ID
	if kicked, err := gruRuntime.ReconnectInterRegion(ctx); kicked != 1 || err != nil {
		t.Fatalf("inbound leaf reconnect = %d, %v", kicked, err)
	}
	waitUntil(t, ctx, "inbound leaf native retry", func() bool {
		leafz, _ := gruRuntime.server.Leafz(nil)
		return len(leafz.Leafs) == 1 && leafz.Leafs[0].ID != inboundID
	})
	probe(ctx)
	assertPreserved()

	// Select whichever URL native retry chose, then silently break that path.
	active, healthy := private, fallback
	if connected := leaf(sfoRuntime); net.JoinHostPort(connected.IP, strconv.Itoa(connected.Port)) == fallback.Addr() {
		active, healthy = fallback, private
	}
	outboundID := leaf(sfoRuntime).ID
	active.Blackhole()
	probeCtx, probeCancel := context.WithTimeout(ctx, 500*time.Millisecond)
	_, err = gruRuntime.Conn().RequestWithContext(probeCtx, subject, []byte("q"))
	probeCancel()
	if err == nil {
		t.Fatal("contract probe succeeded through a blackholed leaf")
	}
	if leaf(sfoRuntime).ID != outboundID {
		t.Fatal("stale leaf disappeared before the reconnect API ran")
	}
	if kicked, err := sfoRuntime.ReconnectInterRegion(ctx); kicked != 1 || err != nil {
		t.Fatalf("stale outbound leaf reconnect = %d, %v", kicked, err)
	}
	repaired, repairedCancel := context.WithTimeout(ctx, 10*time.Second)
	defer repairedCancel()
	waitUntil(t, repaired, "stale leaf retry over the healthy URL", func() bool {
		leafz, _ := sfoRuntime.server.Leafz(nil)
		return len(leafz.Leafs) == 1 && leafz.Leafs[0].ID != outboundID &&
			net.JoinHostPort(leafz.Leafs[0].IP, strconv.Itoa(leafz.Leafs[0].Port)) == healthy.Addr()
	})
	probe(repaired)
	assertPreserved()

	// With both paths closed there is nothing to kick. Healing a path must
	// still recover through the existing remote's retry, without reconfiguring it.
	private.Close()
	fallback.Close()
	waitLeafCount(ctx, t, sfoRuntime, 0)
	if kicked, err := sfoRuntime.ReconnectInterRegion(ctx); kicked != 0 || !errors.Is(err, ErrUnavailable) {
		t.Fatalf("absent leaf reconnect = %d, %v", kicked, err)
	}
	healthy.Reopen(t)
	waitLeafCount(ctx, t, sfoRuntime, 1)
	probe(ctx)
	assertPreserved()
}

func requestUntil(ctx context.Context, t *testing.T, conn *nats.Conn, subject string) *nats.Msg {
	t.Helper()
	for {
		requestCtx, cancel := context.WithTimeout(ctx, 250*time.Millisecond)
		msg, err := conn.RequestWithContext(requestCtx, subject, []byte("q"))
		cancel()
		if err == nil {
			return msg
		}
		if ctx.Err() != nil {
			t.Fatalf("request %q never crossed: %v", subject, err)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func waitStreamMessages(ctx context.Context, t *testing.T, stream jetstream.Stream, want uint64) {
	t.Helper()
	for {
		info, err := stream.Info(ctx)
		if err == nil && info.State.Msgs == want {
			return
		}
		if ctx.Err() != nil {
			t.Fatalf("mirror never reached %d messages: %+v, %v", want, info, err)
		}
		time.Sleep(50 * time.Millisecond)
	}
}

func waitLeafCount(ctx context.Context, t *testing.T, runtime *Runtime, want int) {
	t.Helper()
	for runtime.server.NumLeafNodes() != want {
		if ctx.Err() != nil {
			t.Fatalf("leafnode count = %d, want %d", runtime.server.NumLeafNodes(), want)
		}
		time.Sleep(20 * time.Millisecond)
	}
}

func (region *testRegion) childLeafCredentials(t *testing.T, name, child string) string {
	t.Helper()
	return region.leafCredentialsFor(t, name, region.childKey(t, child), region.interregionID)
}

// leafCredentialsWith issues a user of accountID signed by signer, without
// permissions or limits (as a scoped signing key requires), after mutate
// adjusts its claims, so tests can prove permission-carrying users are refused.
func (region *testRegion) leafCredentialsWith(t *testing.T, name string, signer nkeys.KeyPair, accountID string,
	mutate func(*jwt.UserClaims),
) string {
	t.Helper()
	user, _ := nkeys.CreateUser()
	userID, _ := user.PublicKey()
	claim := jwt.NewUserClaims(userID)
	claim.UserPermissionLimits = jwt.UserPermissionLimits{}
	claim.IssuerAccount = accountID
	mutate(claim)
	raw, err := claim.Encode(signer)
	if err != nil {
		t.Fatal(err)
	}
	seed, _ := user.Seed()
	creds, err := jwt.FormatUserConfig(raw, seed)
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, creds, 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

// leafCredentialsFor issues a user of accountID signed by signer, so tests
// can prove the server refuses leaf users of other accounts or signers.
func (region *testRegion) leafCredentialsFor(t *testing.T, name string, signer nkeys.KeyPair, accountID string) string {
	t.Helper()
	return region.leafCredentialsWith(t, name, signer, accountID, func(*jwt.UserClaims) {})
}

type tcpProxy struct {
	target   string
	addr     string
	mu       sync.Mutex
	listener net.Listener
	conns    []net.Conn
	silent   atomic.Bool
}

// Blackhole drops all traffic from now on without closing anything, as a
// silently failed network path does.
func (p *tcpProxy) Blackhole() { p.silent.Store(true) }

// forward copies src to dst, then closes dst unless the proxy is
// black-holed: a dead path delivers neither data nor the close.
func (p *tcpProxy) forward(dst, src net.Conn) {
	_, _ = io.Copy(proxyWriter{p, dst}, src)
	if !p.silent.Load() {
		_ = dst.Close()
	}
}

// proxyWriter forwards to w until its proxy is black-holed.
type proxyWriter struct {
	proxy *tcpProxy
	w     io.Writer
}

func (p proxyWriter) Write(b []byte) (int, error) {
	if p.proxy.silent.Load() {
		return len(b), nil
	}
	return p.w.Write(b)
}

func newTCPProxy(t *testing.T, target string) *tcpProxy {
	t.Helper()
	proxy := &tcpProxy{target: target}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	proxy.addr = listener.Addr().String()
	proxy.serve(listener)
	return proxy
}

func (p *tcpProxy) Addr() string { return p.addr }

func (p *tcpProxy) serve(listener net.Listener) {
	p.mu.Lock()
	p.listener = listener
	p.mu.Unlock()
	go func() {
		for {
			inbound, err := listener.Accept()
			if err != nil {
				return
			}
			outbound, err := net.Dial("tcp", p.target)
			if err != nil {
				_ = inbound.Close()
				continue
			}
			p.mu.Lock()
			p.conns = append(p.conns, inbound, outbound)
			p.mu.Unlock()
			go p.forward(outbound, inbound)
			go p.forward(inbound, outbound)
		}
	}()
}

func (p *tcpProxy) Close() {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.listener != nil {
		_ = p.listener.Close()
		p.listener = nil
	}
	for _, conn := range p.conns {
		_ = conn.Close()
	}
	p.conns = nil
}

func (p *tcpProxy) Reopen(t *testing.T) {
	t.Helper()
	var listener net.Listener
	var err error
	for range 50 {
		if listener, err = net.Listen("tcp", p.addr); err == nil {
			break
		}
		if !errors.Is(err, syscall.EADDRINUSE) {
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if err != nil {
		t.Fatal(err)
	}
	p.serve(listener)
}

func (ir *InterRegion) validate(cfg Config) error {
	if ir == nil {
		return nil
	}
	if ir.AccountJWTFile == "" {
		return errors.New("interregion account JWT is required")
	}
	if len(ir.Peers) > 63 {
		return errors.New("interregion peers must list at most 63 regions")
	}
	seen := map[string]bool{cfg.Cell: true}
	for _, peer := range ir.Peers {
		if !cellName.MatchString(peer) || peer == protocol.GlobalScope || seen[peer] {
			return fmt.Errorf("interregion peer %q is invalid or repeated", peer)
		}
		seen[peer] = true
	}
	home, err := ir.GlobalControlHome(cfg.Cell)
	if err != nil {
		return err
	}
	// The leaf tree is rooted at the global home. LeafPermissions relies on
	// it: an accepted leaf never speaks for the home, so a home that dialed
	// a parent would have its health, queries and mirror feeds refused there.
	if home == cfg.Cell && len(ir.Remotes) != 0 {
		return errors.New("the interregion global home is the leaf tree root and must not dial remotes")
	}
	if len(ir.Peers) != 0 && ir.Listen == nil && len(ir.Remotes) == 0 {
		return errors.New("interregion needs a leaf listener or at least one remote")
	}
	// The home is the tree root and never dials out, so a non-home region
	// reaches it, and its mirror feed, only through a parent remote.
	if home != cfg.Cell && len(ir.Remotes) == 0 {
		return errors.New("a non-home region must dial a remote to reach the interregion global home")
	}
	if ir.Listen != nil && (ir.Listen.Host != "0.0.0.0" || ir.Listen.Port <= 0 || !ir.Listen.TLS.complete()) {
		return errors.New("interregion leaf listener requires host 0.0.0.0, port, and mutual TLS")
	}
	if (ir.Listen != nil) != (len(ir.Subtrees) != 0) {
		return errors.New("interregion leaf listener and child subtrees must be configured together")
	}
	reached := map[string]bool{}
	for child, subtree := range ir.Subtrees {
		if !slices.Contains(subtree, child) {
			return fmt.Errorf("interregion child %q must be in its own subtree", child)
		}
		for _, region := range subtree {
			if !slices.Contains(ir.Peers, region) || region == home || reached[region] {
				return fmt.Errorf("interregion subtree of %q names %q, which is not a unique non-home peer", child, region)
			}
			reached[region] = true
		}
	}
	// The tree root (no parent remote) reaches every peer through its child
	// subtrees; a peer in none would be in the contract yet unreachable,
	// and every request to it would hang without a responder. A region
	// with a parent reaches the rest of the tree through it.
	if len(ir.Remotes) == 0 {
		for _, peer := range ir.Peers {
			if !reached[peer] {
				return fmt.Errorf("interregion roster peer %q is in no child subtree and this region dials no parent", peer)
			}
		}
	}
	remotes := map[string]bool{}
	for _, remote := range ir.Remotes {
		if !slices.Contains(ir.Peers, remote.Peer) || remotes[remote.Peer] || reached[remote.Peer] {
			return fmt.Errorf("interregion remote %q is not a unique roster peer outside the child subtrees", remote.Peer)
		}
		remotes[remote.Peer] = true
		if len(remote.URLs) == 0 || remote.CredentialsFile == "" || !remote.TLS.complete() ||
			!nkeys.IsValidPublicAccountKey(remote.PeerAccount) {
			return fmt.Errorf("interregion remote %q requires URLs, credentials, peer account, and mutual TLS", remote.Peer)
		}
		if len(remote.ServerName) > 253 || !leafServerName.MatchString(remote.ServerName) || net.ParseIP(remote.ServerName) != nil {
			return fmt.Errorf("interregion remote %q server_name must be a DNS name", remote.Peer)
		}
		for _, raw := range remote.URLs {
			parsed, err := url.Parse(raw)
			if err != nil || parsed.Scheme != "nats-leaf" || parsed.Host == "" || parsed.User != nil ||
				parsed.Path != "" || parsed.RawQuery != "" {
				return fmt.Errorf("interregion remote %q URL must be nats-leaf://host:port", remote.Peer)
			}
		}
	}
	return nil
}

func interRegionServerOptions(cfg Config, options *server.Options, resolver *accountResolver,
	operator *jwt.OperatorClaims,
) error {
	ir := cfg.Embedded.InterRegion
	raw, err := readSignedJWT(ir.AccountJWTFile)
	if err != nil {
		return fmt.Errorf("read interregion account JWT: %w", err)
	}
	claim, err := jwt.DecodeAccountClaims(raw)
	if err != nil || !nkeys.IsValidPublicAccountKey(claim.Subject) || !operator.DidSign(claim) ||
		claim.Subject == resolver.system || claim.Subject == resolver.cell {
		return errors.New("interregion account JWT is invalid")
	}
	systemClaim, err := jwt.DecodeAccountClaims(resolver.claims[resolver.system])
	if err != nil {
		return err
	}
	cellClaim, err := jwt.DecodeAccountClaims(resolver.claims[resolver.cell])
	if err != nil {
		return err
	}
	contract, links, err := ir.Contract(cfg.Cell)
	if err != nil {
		return err
	}
	if err := contract.verify(systemClaim, cellClaim, claim, links); err != nil {
		return err
	}
	resolver.admitInterRegion(claim.Subject, raw, contract, links)
	options.LeafNode.NoAdvertise = true
	// Leafnodes have no ping knob of their own. With these, a silently
	// dropped path is closed after 3 unanswered pings and the remote fails
	// over to its next URL within about 40 s, not the default 2 minutes and
	// 2 pings. Routes (otherwise 30 s and 2 pings) and bridged clients get
	// the same faster stale detection.
	options.PingInterval, options.MaxPingsOut = 10*time.Second, 3
	if ir.Listen != nil {
		listenTLS, err := loadTLS(ir.Listen.TLS, true)
		if err != nil {
			return fmt.Errorf("interregion leaf listener TLS: %w", err)
		}
		options.LeafNode.Host = ir.Listen.Host
		options.LeafNode.Port = ir.Listen.Port
		options.LeafNode.TLSConfig = listenTLS
		options.LeafNode.TLSTimeout = 5
	}
	for _, remote := range ir.Remotes {
		if err := validateLeafCredentials(remote.CredentialsFile, remote.PeerAccount); err != nil {
			return fmt.Errorf("interregion remote %q: %w", remote.Peer, err)
		}
		remoteTLS, err := loadTLS(remote.TLS, false)
		if err != nil {
			return fmt.Errorf("interregion remote %q TLS: %w", remote.Peer, err)
		}
		// NATS otherwise names the TLS server after the first non-IP URL,
		// or each IP itself.
		remoteTLS.ServerName = remote.ServerName
		leaf := &server.RemoteLeafOpts{
			LocalAccount: claim.Subject, Credentials: remote.CredentialsFile,
			TLS: true, TLSConfig: remoteTLS, TLSTimeout: 5, NoRandomize: true,
		}
		for _, raw := range remote.URLs {
			parsed, err := url.Parse(raw)
			if err != nil {
				return err
			}
			leaf.URLs = append(leaf.URLs, parsed)
		}
		options.LeafNode.Remotes = append(options.LeafNode.Remotes, leaf)
	}
	return nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func serverOptions(cfg Config) (*server.Options, error) {
	return serverOptionsForStart(cfg, false)
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func readNodeIdentity(t *testing.T, dir string) nodeIdentity {
	t.Helper()
	wire, err := os.ReadFile(filepath.Join(dir, nodeIdentityFile))
	if err != nil {
		t.Fatal(err)
	}
	var identity nodeIdentity
	if err := json.Unmarshal(wire, &identity); err != nil {
		t.Fatal(err)
	}
	return identity
}

