func serverOptions(cfg Config) (*server.Options, error) {
	return serverOptionsForStart(cfg, false)
}

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}
	if identityRekey && (e.InterRegion != nil || e.Link != nil) {
		options.LeafNode = server.LeafNodeOpts{}
	}
	if cfg.Replicas > 1 {
		for _, raw := range e.Routes {
			route, err := url.Parse(raw)
			if err != nil || route.Host == "" || route.User != nil || route.Scheme != "nats-route" {
				return nil, fmt.Errorf("invalid NATS route %q", raw)
			}
			options.Routes = append(options.Routes, route)
		}
	}
	if cfg.Replicas > 1 && e.RouteTLS.complete() {
		// Routes reload a renewed leaf or CA bundle on their next handshake.
		routeTLS, err := NewReloadingTLS(e.RouteTLS, "route")
		if err != nil {
			return nil, err
		}
		options.Cluster.TLSConfig = routeTLS.PeerConfig()
	}
	seenKeys := make(map[string]struct{}, len(e.Users))
	for _, user := range e.Users {
		if !nkeys.IsValidPublicUserKey(user.PublicKey) {
			return nil, errors.New("invalid user NKey in embedded NATS users")
		}
		if _, exists := seenKeys[user.PublicKey]; exists {
			return nil, errors.New("duplicate embedded NATS user key")
		}
		seenKeys[user.PublicKey] = struct{}{}
		permissions, err := userPermissions(cfg.Cell, user)
		if err != nil {
			return nil, err
		}
		options.Nkeys = append(options.Nkeys, &server.NkeyUser{Nkey: user.PublicKey, Permissions: permissions})
	}
	if e.RoutePasswordFile != "" {
		secret, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return nil, fmt.Errorf("read NATS route secret: %w", err)
		}
		defer clear(secret)
		password := strings.TrimSpace(string(secret))
		if len(password) < 16 {
			return nil, errors.New("NATS route secret must be at least 16 bytes")
		}
		options.Cluster.Username = e.RouteUser
		options.Cluster.Password = password
		for _, route := range options.Routes {
			route.User = url.UserPassword(e.RouteUser, password)
		}
	}
	return options, nil
}

func pinStoreIdentity(dir, name, legacy string) error {
	path := filepath.Join(dir, storeIdentityFile)
	recorded, err := os.ReadFile(path)
	if err == nil {
		if owner := strings.TrimSuffix(string(recorded), "\n"); owner != name {
			return fmt.Errorf("%w: store %s belongs to %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, owner, name)
		}
		return nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("read NATS store identity: %w", err)
	}
	if name != legacy {
		entries, err := os.ReadDir(filepath.Join(dir, "jetstream"))
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read NATS store: %w", err)
		}
		if len(entries) > 0 {
			return fmt.Errorf("%w: store %s holds JetStream state of %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, legacy, name)
		}
	}
	temp, err := os.CreateTemp(dir, storeIdentityFile+".*")
	if err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	defer os.Remove(temp.Name())
	if _, err := temp.WriteString(name + "\n"); err != nil {
		temp.Close()
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	return os.Rename(temp.Name(), path)
}

func NATSServer(cell, instance string) string {
	if name, err := RegionCell(cell).ControllerSlot(instance); err == nil {
		return name
	}
	return cell + "-" + instance
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

// Image returns the name of the cell's qualified ARM64 host image, e.g.
// gru-1-arm64. A new image import reuses the name; the source revision and
// digest belong in its signed receipt.
func (c Cell) Image() (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	return name + "-arm64", nil
}

// Node returns the name of the region's n-th node, e.g. ts-gru-1.
func (c Cell) Node(n int) (string, error) {
	return valid(fmt.Sprintf("ts-%s-%d", strings.ToLower(c.Region), n))
}

// Server returns the name of the cell's n-th server of role, e.g. gru-1-ctl-1.
func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// PoolServer returns the name of the n-th host of a node pool, e.g.
// gru-1-pool-app-3. A pool name is 2 to 12 lower-case letters and digits,
// starting with a letter.
func (c Cell) PoolServer(pool string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-pool-%s-%d", strings.ToLower(c.Region), c.Index, pool, n))
}

// ControllerSlot returns the server name of a signed controller slot:
// controller-a, -b and -c are the region's nodes 1, 2 and 3 (ts-sfo-1). GRU
// keeps ctl-1, -2 and -3 (gru-1-ctl-1) until its servers are renamed: a
// controller refuses a NATS store of another server name.
func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

// MemberSlot returns the server name of a regional plan's database host
// slot: member-a and -b are db-1 and -2.
func (c Cell) MemberSlot(slot string) (string, error) { return c.slot(slot, "member-", Member) }

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

